demo.seatActive=(agent,active)=>{
  if(AccountSeat.scopeError(agent.tenantId,agent.enterpriseId))return false;
  if(AccountSeat.inUse(agent)){showToast('请先结束通话、完成话后处理并下线，再修改坐席配置','warning');return false;}
  const fields={...AliCtiFields.authFields(agent.enterpriseId).fields,cno:agent.cno,active,power:AliCtiFields.seatFields(agent).power};
  const isOb=agent.callEnabled===false?0:1;
  const auth=AliCtiFields.authFields(agent.enterpriseId);if(auth.pending.length)return false;
  const response=demo.seatUpdateOutcome==='unknown'?null:demo.seatUpdateOutcome==='failure'?{result:-1,errorCode:20023,description:'座席状态在线（模拟）'}:{result:0,data:{agent:{cno:agent.cno,active,isOb}}};
  demo.lastSeatUpdate={endpoint:'agent/update',fields,response,queries:response?.result===0?[{endpoint:'agent/get',fields:{...auth.fields,cno:agent.cno},response:{result:0,data:{agent:{cno:agent.cno,active,isOb}}}},{endpoint:'agentStatus/get',fields:{...auth.fields,cno:agent.cno},response:{result:0,data:{state:'离线',loginStatus:0}}}]:[],mock:true};
  root.AliCtiAdapter.lastRequest=demo.lastSeatUpdate;
  if(response?.result!==0){showToast(response?'坐席状态已变化，请先下线再修改（模拟）':'修改结果待核对，原配置保留','warning');return false;}return true;
};

function persistAgent(agent, relations) {
  if (!agent || scopeError(agent.tenantId, agent.enterpriseId)) return false;
  try {
    const saved = read(); putSeat(saved, agent);
    if (relations) {
      saved.skillAssignments = (saved.skillAssignments || []).filter(r => r.identityId !== agent.contactCenterIdentityId);
      saved.skillAssignments.push({ identityId: agent.contactCenterIdentityId, tenantId: agent.tenantId, enterpriseId: agent.enterpriseId, relations: clone(relations) });
    }
    write(saved); restore(saved); return true;
  }
  catch (_) { showToast('坐席变更暂未保存，请保留当前页面重试', 'warning'); return false; }
}

  const opts = options || {};
  const id = opts.id || 'platform-confirm';
  openLayer(id, `<div class="layer-header"><h2>${escape(opts.title || '确认操作')}</h2><button type="button" onclick="PlatformUI.closeLayer('${id}')">×</button></div><div class="layer-body">${opts.body || ''}</div><div class="layer-footer"><button class="btn btn-default" type="button" onclick="PlatformUI.closeLayer('${id}')">${escape(opts.cancelText || '取消')}</button><button class="btn btn-primary ${opts.danger ? 'btn-danger' : ''}" id="${id}-confirm" type="button">${escape(opts.confirmText || '确认')}</button></div>`, 'small', {kind:'confirmation'});
  const button = document.getElementById(`${id}-confirm`);
  if (button) button.onclick = () => { if (typeof opts.onConfirm === 'function' && opts.onConfirm() === false) return; closeLayer(id); };
}

